// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager, EscalationManagerInterface} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;

    function setUp() public {
        c = new BaseEscalationManager(address(new __InvMutHandleStub()));
    }

    function testFuzz_property(bytes32 assertionId) public {
        EscalationManagerInterface.AssertionPolicy memory policy = c.getAssertionPolicy(assertionId);
        assertTrue(
            policy.blockAssertion == false &&
            policy.arbitrateViaEscalationManager == false &&
            policy.discardOracle == false &&
            policy.validateDisputers == false
        );
    }
}

